<?php
declare(strict_types=1);
require_once __DIR__.'/config/seguridad.php';require_once __DIR__.'/config/conexion.php';require_once __DIR__.'/config/utilidades.php';exigirAdmin();
$error='';$mensaje='';$editar=null;$roles=['admin','editor','redactor'];
try{
 if($_SERVER['REQUEST_METHOD']==='POST'){
  validarCsrf();$accion=$_POST['accion']??'';$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT)?:0;
  if($accion==='eliminar'){
   if($id===(int)$_SESSION['usuario_id'])throw new RuntimeException('No puedes eliminar tu propia cuenta.');
   $conexion->prepare('DELETE FROM usuarios WHERE id=?')->execute([$id]);$mensaje='Usuario eliminado correctamente.';
  }else{
   $nombres=trim($_POST['nombres']??'');$paterno=trim($_POST['ap_paterno']??'');$materno=trim($_POST['ap_materno']??'');$email=trim($_POST['email']??'');$rol=$_POST['rol']??'';$clave=$_POST['password']??'';
   if($nombres===''||$paterno===''||$email==='')throw new RuntimeException('Completa todos los campos obligatorios.');
   if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('El correo electrónico no es válido.');
   if(!in_array($rol,$roles,true))throw new RuntimeException('El rol no es válido.');
   if($id===0||$clave!=='')authPassword($clave);
   if($id===(int)$_SESSION['usuario_id']&&$rol!=='admin')throw new RuntimeException('No puedes quitarte tu propio permiso de administrador.');
   $q=$conexion->prepare('SELECT id FROM usuarios WHERE email=? AND id<>?');$q->execute([$email,$id]);if($q->fetch())throw new RuntimeException('Ese correo ya está registrado.');
   if($id){
    $sql='UPDATE usuarios SET nombres=?,ap_paterno=?,ap_materno=?,email=?,rol=?';$datos=[$nombres,$paterno,$materno?:null,$email,$rol];if($clave!==''){$sql.=',password_hash=?';$datos[]=password_hash($clave,PASSWORD_DEFAULT);}$sql.=' WHERE id=?';$datos[]=$id;$conexion->prepare($sql)->execute($datos);$mensaje='Usuario actualizado correctamente.';
    if($id===(int)$_SESSION['usuario_id']){$_SESSION['usuario_nombre']=trim("$nombres $paterno $materno");$_SESSION['usuario_email']=$email;}
   }else{$conexion->prepare('INSERT INTO usuarios(nombres,ap_paterno,ap_materno,email,password_hash,rol) VALUES(?,?,?,?,?,?)')->execute([$nombres,$paterno,$materno?:null,$email,password_hash($clave,PASSWORD_DEFAULT),$rol]);$mensaje='Usuario registrado correctamente.';}
  }
 }
}catch(Throwable $ex){$error=$ex instanceof PDOException?'No se pudo completar la operación. El usuario puede tener publicaciones relacionadas.':$ex->getMessage();}
$idEditar=filter_input(INPUT_GET,'editar',FILTER_VALIDATE_INT)?:0;if($idEditar){$q=$conexion->prepare('SELECT id,nombres,ap_paterno,ap_materno,email,rol FROM usuarios WHERE id=?');$q->execute([$idEditar]);$editar=$q->fetch()?:null;}
$usuarios=$conexion->query('SELECT id,nombres,ap_paterno,ap_materno,email,rol,created_at FROM usuarios ORDER BY id DESC')->fetchAll();$tituloPagina='Administración de usuarios';$paginaActiva='usuarios';require __DIR__.'/partials/head.php';
?>
<section class="section-hero"><div class="d-flex align-items-center gap-3 position-relative" style="z-index:2"><div class="section-icon">👥</div><div><div class="small opacity-75 mb-1">SEGURIDAD Y ACCESO</div><h1>Administración de usuarios</h1><p>Gestiona las cuentas, credenciales y permisos del panel.</p></div></div></section>
<?php if($mensaje):?><div class="alert alert-success"><?=e($mensaje)?></div><?php endif?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif?>
<?php $conteoRoles=array_count_values(array_column($usuarios,'rol'));?>
<div class="row g-3 mb-4"><?php foreach([['👥','Usuarios',count($usuarios),'soft-blue'],['🛡️','Administradores',$conteoRoles['admin']??0,'soft-purple'],['📝','Editores',$conteoRoles['editor']??0,'soft-cyan'],['✏️','Redactores',$conteoRoles['redactor']??0,'soft-orange']] as [$ico,$nombre,$cantidad,$color]):?><div class="col-6 col-xl-3"><div class="card"><div class="card-body d-flex align-items-center gap-3"><span class="metric-icon <?=$color?>"><?=$ico?></span><div><small class="text-muted"><?=e($nombre)?></small><div class="fs-3 fw-bold"><?=$cantidad?></div></div></div></div></div><?php endforeach?></div>
<div class="row g-4"><div class="col-xl-4"><div class="card sticky-form"><div class="card-header bg-transparent border-bottom py-3 px-4"><div class="d-flex align-items-center gap-3"><span class="metric-icon soft-blue"><?=$editar?'✏️':'＋'?></span><div><div class="panel-title"><?=$editar?'Editar usuario':'Nuevo usuario'?></div><small class="text-muted">Datos personales y acceso</small></div></div></div><div class="card-body p-4"><form method="post"><input type="hidden" name="csrf_token" value="<?=e(tokenCsrf())?>"><input type="hidden" name="accion" value="guardar"><input type="hidden" name="id" value="<?=e($editar['id']??'')?>">
<?php foreach(['nombres'=>'Nombres','ap_paterno'=>'Apellido paterno','ap_materno'=>'Apellido materno','email'=>'Correo electrónico'] as $campo=>$etiqueta):$obligatorio=in_array($campo,['nombres','ap_paterno','email'],true);?><div class="mb-3"><label class="form-label"><?=e($etiqueta)?><?=$obligatorio?' <span class="text-danger">*</span>':''?></label><input class="form-control" type="<?=$campo==='email'?'email':'text'?>" name="<?=e($campo)?>" value="<?=e($editar[$campo]??'')?>" <?=$obligatorio?'required':''?>></div><?php endforeach?>
<div class="mb-3"><label class="form-label">Contraseña <?=$editar?'<span class="text-muted">(opcional)</span>':'<span class="text-danger">*</span>'?></label><div class="input-group"><input id="claveUsuario" class="form-control" type="password" name="password" minlength="12" maxlength="72" <?=$editar?'':'required'?>><button id="verClave" class="btn btn-outline-secondary" type="button">👁</button></div><small class="text-muted">Utiliza como mínimo 12 caracteres.</small></div><div class="mb-4"><label class="form-label">Rol <span class="text-danger">*</span></label><select class="form-select" name="rol" required><?php foreach($roles as $rol):?><option value="<?=$rol?>" <?=($editar['rol']??'redactor')===$rol?'selected':''?>><?=e(ucfirst($rol))?></option><?php endforeach?></select><small class="text-muted d-block mt-1">Administrador: acceso total. Editor: contenidos. Redactor: sus reportajes, sin eliminar ni destacar.</small></div><div class="d-flex gap-2"><button class="btn btn-primary flex-grow-1">✓ Guardar usuario</button><?php if($editar):?><a class="btn btn-light" href="usuarios.php">Cancelar</a><?php endif?></div></form></div></div></div>
<div class="col-xl-8"><div class="card"><div class="card-header bg-transparent border-bottom py-3 px-4"><div class="d-flex justify-content-between align-items-center"><div><div class="panel-title">Equipo de administración</div><small class="text-muted">Usuarios autorizados para ingresar al sistema</small></div><span class="record-count"><?=count($usuarios)?> usuario(s)</span></div></div><div class="card-body p-0"><div class="table-responsive"><table class="table table-modern mb-0"><thead><tr><th>Usuario</th><th>Correo</th><th>Rol</th><th>Registro</th><th>Acciones</th></tr></thead><tbody><?php foreach($usuarios as $u):$nombreCompleto=trim($u['nombres'].' '.$u['ap_paterno'].' '.($u['ap_materno']??''));?><tr data-fila><td><div class="d-flex align-items-center gap-3"><div class="avatar" style="width:39px;height:39px"><?=e(strtoupper(substr($nombreCompleto,0,1)))?></div><div><strong><?=e($nombreCompleto)?></strong><?php if((int)$u['id']===(int)$_SESSION['usuario_id']):?><small class="d-block text-primary">Sesión actual</small><?php endif?></div></div></td><td><?=e($u['email'])?></td><td><span class="badge rounded-pill bg-<?=$u['rol']==='admin'?'primary':($u['rol']==='editor'?'info text-dark':'secondary')?>"><?=e(ucfirst($u['rol']))?></span></td><td><?=e(date('d/m/Y',strtotime($u['created_at'])))?></td><td class="text-nowrap"><a class="btn btn-sm btn-outline-primary" title="Editar" href="?editar=<?=$u['id']?>">✏️</a><?php if((int)$u['id']!==(int)$_SESSION['usuario_id']):?><form method="post" class="d-inline" onsubmit="return confirm('¿Eliminar este usuario?')"><input type="hidden" name="csrf_token" value="<?=e(tokenCsrf())?>"><input type="hidden" name="accion" value="eliminar"><input type="hidden" name="id" value="<?=$u['id']?>"><button class="btn btn-sm btn-outline-danger" title="Eliminar">🗑️</button></form><?php endif?></td></tr><?php endforeach?></tbody></table></div></div></div></div></div>
<script>document.getElementById('verClave')?.addEventListener('click',()=>{const c=document.getElementById('claveUsuario');c.type=c.type==='password'?'text':'password'});</script>
<?php require __DIR__.'/partials/footer.php';
